import { handleEndpoints } from 'payload'
import config from '../../../payload.config'
import { NextRequest } from 'next/server'

/**
 * Payload CMS Admin Panel Route
 * 
 * This route handles all Payload admin panel requests at /admin/*
 * The admin panel is served through Payload's handleEndpoints function.
 * 
 * WHY THIS WAS RETURNING 404:
 * - The route.ts file was correctly created, but the path handling needed adjustment
 * - Payload expects the path relative to the basePath, not the full URL path
 * - The basePath parameter tells Payload where the admin is mounted
 */
async function handleRequest(request: NextRequest) {
  try {
    const url = new URL(request.url)
    const originalPathname = url.pathname
    
    // Extract the path after /admin (this is what Payload expects)
    // For /admin -> '', for /admin/login -> '/login', for /admin/globals/homePage -> '/globals/homePage'
    let pathname = originalPathname.replace(/^\/admin/, '')
    
    // Normalize: remove trailing slash and ensure it starts with / if not empty
    if (pathname.endsWith('/') && pathname !== '/') {
      pathname = pathname.slice(0, -1)
    }
    if (pathname !== '' && !pathname.startsWith('/')) {
      pathname = '/' + pathname
    }
    
    // Debug logging in development
    if (process.env.NODE_ENV === 'development') {
      console.log('[Payload Admin] Original path:', originalPathname)
      console.log('[Payload Admin] Processed pathname:', pathname || '(empty - root)')
    }
    
    // Get request body if it exists
    let body: BodyInit | undefined
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      try {
        body = await request.text()
      } catch {
        body = undefined
      }
    }
    
    // Create a new Request object for Payload's handleEndpoints
    // The URL should NOT include /admin since basePath handles that
    // For root admin (pathname === ''), use '/' in the URL
    const urlPath = pathname === '' ? '/' : pathname
    const payloadRequest = new Request(
      new URL(urlPath + url.search, url.origin),
      {
        method: request.method,
        headers: Object.fromEntries(request.headers.entries()),
        body: body,
      }
    )
    
    // Use handleEndpoints from Payload 3.x
    // basePath tells Payload the admin is mounted at /admin
    // path is the route relative to basePath - empty string '' for root admin
    const response = await handleEndpoints({
      config,
      request: payloadRequest,
      path: pathname, // Empty string '' for /admin root, '/login' for /admin/login, etc.
      basePath: '/admin',
    })
    
    // Log response status in development
    if (process.env.NODE_ENV === 'development') {
      console.log('[Payload Admin] Response status:', response.status)
    }
    
    return response
  } catch (error) {
    // Log detailed error for server-side debugging
    console.error('Error handling Payload admin request:', error)
    if (error instanceof Error) {
      console.error('Error details:', {
        message: error.message,
        stack: error.stack,
        name: error.name
      })
    }
    
    // Return error response with more details (in development)
    const isDevelopment = process.env.NODE_ENV === 'development'
    return new Response(
      JSON.stringify({ 
        error: 'Internal Server Error',
        message: error instanceof Error ? error.message : 'Unknown error',
        ...(isDevelopment && error instanceof Error ? { 
          details: error.stack,
          hint: 'Check server console logs for database connection errors. Ensure PostgreSQL is installed and running, and DATABASE_URL is correctly configured in .env.local'
        } : {})
      }),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    )
  }
}

export async function GET(request: NextRequest) {
  return handleRequest(request)
}

export async function POST(request: NextRequest) {
  return handleRequest(request)
}

export async function PUT(request: NextRequest) {
  return handleRequest(request)
}

export async function PATCH(request: NextRequest) {
  return handleRequest(request)
}

export async function DELETE(request: NextRequest) {
  return handleRequest(request)
}

